95: export const createWorkshop = form(
96: 	CreateWorkshopRemoteSchema,
97: 	async (data, issue) => {
98: 		const event = getRequestEvent();
99: 		await authorize(event.locals, "workshops.manage");
100: 
101: 		// Cross-field validations
102: 		const startDate = new Date(data.workshop_date);
103: 		const endDate = new Date(data.workshop_end_date);
104: 
105: 		if (startsDublinToday(startDate)) {
106: 			throw new Error("Workshop cannot be scheduled for today");
107: 		}
108: 
109: 		if (!(endDate.getTime() > startDate.getTime())) {
110: 			throw new Error("End time cannot be before start time");
111: 		}
112: 
113: 		// Normalise the submitted instants to ISO strings and prices to cents
114: 		const startDateTime = startDate.toISOString();
115: 		const endDateTime = endDate.toISOString();
116: 
117: 		const memberPriceCents = Dinero({
118: 			amount: Math.round(data.price_member * 100),
119: 			currency: "EUR",
120: 		}).getAmount();
121: 
122: 		const nonMemberPriceCents =
123: 			data.is_public && data.price_non_member
124: 				? Dinero({
125: 						amount: Math.round(data.price_non_member * 100),
126: 						currency: "EUR",
127: 					}).getAmount()
128: 				: memberPriceCents;
129: 
130: 		const workshopData: WorkshopManagementRequest = {
131: 			title: data.title,
132: 			description: data.description || null,
133: 			location: data.location,
134: 			...destinationPayload(data),
135: 			startDate: startDateTime,
136: 			endDate: endDateTime,
137: 			maxCapacity: data.max_capacity,
138: 			priceMember: memberPriceCents,
139: 			priceNonMember: nonMemberPriceCents,
140: 			isPublic: data.is_public || false,
141: 			refundDays: data.refund_deadline_days ?? 0,
142: 			announceDiscord: data.announce_discord || false,
143: 			announceEmail: data.announce_email || false,
144: 		};
145: 
146: 		const result = await commandResult(
147: 			workshopsCreate({
148: 				...apiClientOptions(event.cookies),
149: 				body: workshopData,
150: 			}),
151: 			"Failed to create workshop. Please try again later.",
152: 			attributeDestinationRejection(issue),
