168: export const updateWorkshop = form(
169: 	UpdateWorkshopRemoteSchema,
170: 	async (data, issue) => {
171: 		const event = getRequestEvent();
172: 		await authorize(event.locals, "workshops.manage");
173: 		const workshopId = event.params.id;
174: 
175: 		if (!workshopId) {
176: 			throw new Error("Workshop ID is required");
177: 		}
178: 
179: 		// The form submits the start on every save, so judge a start on Dublin's
180: 		// today against the saved one: moving a workshop onto today is refused,
181: 		// like scheduling it for today, but a workshop already taking place today
182: 		// can still be edited. Only a start on today costs the extra read.
183: 		if (data.workshop_date) {
184: 			const now = new Date();
185: 			const start = new Date(data.workshop_date);
186: 			if (startsDublinToday(start, now)) {
187: 				const current = await workshopsShow({
188: 					...apiClientOptions(event.cookies),
189: 					path: { workshopId },
190: 				});
191: 				if (current.error) {
192: 					throw new Error(
193: 						apiErrorMessage(
194: 							current.error,
195: 							"Failed to update workshop. Please try again later.",
196: 						),
197: 					);
198: 				}
199: 				const persisted = new Date(current.data.data.workshop.startDate);
200: 				if (movesOntoDublinToday(start, persisted, now)) {
201: 					throw new Error("Workshop cannot be scheduled for today");
202: 				}
203: 			}
204: 		}
205: 
206: 		// Transform form data to database format
207: 		const updateData: WorkshopManagementUpdateRequest = {
208: 			title: data.title,
209: 			description: data.description || null,
210: 			location: data.location,
211: 			// The edit form submits the destination fields it prefilled, so an
212: 			// unrelated edit resubmits the stored values (preserving them) and an
213: 			// emptied field is an explicit clear (null).
214: 			...destinationPayload(data),
215: 			// Pass the submitted instants through untouched: the form keeps both
216: 			// fields coherent when only the date or only the time changes. Do NOT
217: 			// rebuild endDate from startDate plus endDate's local time-of-day — that
218: 			// silently drops a midnight rollover whenever the Workshop crosses days,
219: 			// producing an end_date before start_date.
220: 			startDate: data.workshop_date
221: 				? new Date(data.workshop_date).toISOString()
222: 				: undefined,
223: 			endDate: data.workshop_end_date
