import * as v from "valibot";
import { dublinToday } from "#lib/club-calendar.js";

/**
 * Whether a workshop starting at `start` would start on Dublin's today, as
 * read at `now`. Both sides are Dublin days, so the check holds between
 * midnight and 01:00 in Irish Summer Time, when the UTC date is still
 * yesterday's.
 */
export function startsDublinToday(start: Date, now: Date = new Date()) {
	return dublinToday(start) === dublinToday(now);
}

/**
 * Whether an edit that moves a workshop's start from `persisted` to `start`
 * puts it on Dublin's today, as read at `now`. A workshop already taking
 * place today may keep its day (and move its time within it): the edit form
 * submits the start on every save, so only a move onto today is refused.
 */
export function movesOntoDublinToday(
	start: Date,
	persisted: Date,
	now: Date = new Date(),
) {
	return startsDublinToday(start, now) && !startsDublinToday(persisted, now);
}

const isHttpsUrl = (input: string) => {
	try {
		return new URL(input).protocol === "https:";
	} catch {
		return false;
	}
};

/**
 * Optional destination details (ALE-440), kept separate from the required
 * short venue label. Client-side the directions link only gets a light
 * https-shape check; Phoenix owns the supported-Maps-destination rule and
 * answers a rejection as a field error on `directionsUrl`.
 */
export const destinationDetails = {
	destination_name: v.optional(v.pipe(v.string(), v.maxLength(255)), ""),
	destination_address: v.optional(v.pipe(v.string(), v.maxLength(500)), ""),
	directions_url: v.optional(
		v.pipe(
			v.string(),
			v.maxLength(2048),
			v.check(
				(input) => input.trim() === "" || isHttpsUrl(input),
				"Directions link must be an https link",
			),
		),
		"",
	),
};

export const BaseWorkshopSchema = v.object({
	title: v.pipe(
		v.string(),
		v.minLength(1, "Title is required"),
		v.maxLength(255),
	),
	description: v.optional(v.string(), ""),
	location: v.pipe(v.string(), v.minLength(1, "Location is required")),
	destination_name: destinationDetails.destination_name,
	destination_address: destinationDetails.destination_address,
	directions_url: destinationDetails.directions_url,
	workshop_date: v.pipe(
		v.date(),
		v.check(
			(date) => !startsDublinToday(date),
			"Workshop cannot be scheduled for today",
		),
	),
	workshop_end_date: v.date(),
	max_capacity: v.pipe(
		v.number(),
		v.minValue(1, "Capacity must be at least 1"),
	),
	price_member: v.pipe(v.number(), v.minValue(0, "Price cannot be negative")),
	price_non_member: v.optional(
		v.pipe(v.number(), v.minValue(0, "Price cannot be negative")),
	),
	is_public: v.optional(v.boolean(), false),
	refund_deadline_days: v.nullable(
		v.pipe(v.number(), v.minValue(0, "Refund deadline cannot be negative")),
	),
	announce_discord: v.optional(v.boolean(), false),
	announce_email: v.optional(v.boolean(), false),
});

export const CreateWorkshopSchema = v.pipe(
	BaseWorkshopSchema,
	v.forward(
		v.partialCheck(
			[["workshop_date"], ["workshop_end_date"]],
			({ workshop_date, workshop_end_date }) =>
				workshop_end_date.getTime() > workshop_date.getTime(),
			"End time cannot be before start time",
		),
		["workshop_end_date"],
	),
);

export type CreateWorkshopInput = v.InferOutput<typeof CreateWorkshopSchema>;

/**
 * Coerces string "true"/"false" to boolean for hidden input fields.
 * Hidden inputs send string values, so we need to transform them.
 */
const booleanFromString = v.pipe(
	v.union([v.boolean(), v.literal("true"), v.literal("false"), v.undefined()]),
	v.transform((val) => val === true || val === "true"),
);

/**
 * Remote schema for create - dates as ISO strings for serialization.
 * Remote Functions serialize data, so we can't pass Date objects directly.
 */
export const CreateWorkshopRemoteSchema = v.object({
	title: v.pipe(
		v.string(),
		v.minLength(1, "Title is required"),
		v.maxLength(255),
	),
	description: v.optional(v.string(), ""),
	location: v.pipe(v.string(), v.minLength(1, "Location is required")),
	destination_name: destinationDetails.destination_name,
	destination_address: destinationDetails.destination_address,
	directions_url: destinationDetails.directions_url,
	workshop_date: v.pipe(v.string(), v.nonEmpty("Workshop date is required")),
	workshop_end_date: v.pipe(
		v.string(),
		v.nonEmpty("Workshop end date is required"),
	),
	max_capacity: v.pipe(
		v.number(),
		v.minValue(1, "Capacity must be at least 1"),
	),
	price_member: v.pipe(v.number(), v.minValue(0, "Price cannot be negative")),
	price_non_member: v.optional(
		v.pipe(v.number(), v.minValue(0, "Price cannot be negative")),
	),
	is_public: v.optional(booleanFromString, false),
	refund_deadline_days: v.optional(
		v.pipe(v.number(), v.minValue(0, "Refund deadline cannot be negative")),
	),
	announce_discord: v.optional(booleanFromString, false),
	announce_email: v.optional(booleanFromString, false),
});

/**
 * Remote schema for update - all fields optional, dates as strings.
 */
export const UpdateWorkshopRemoteSchema = v.partial(CreateWorkshopRemoteSchema);

export type CreateWorkshopRemoteInput = v.InferInput<
	typeof CreateWorkshopRemoteSchema
>;
export type UpdateWorkshopRemoteInput = v.InferInput<
	typeof UpdateWorkshopRemoteSchema
>;

