<script lang="ts">
import { resolve } from "$app/paths";
import { Badge } from "#lib/components/ui/badge/index.js";
import { Button } from "#lib/components/ui/button/index.js";
import {
	ToggleGroup,
	ToggleGroupItem,
} from "#lib/components/ui/toggle-group/index.js";
import * as Dialog from "#lib/components/ui/dialog/index.js";
import { Input } from "#lib/components/ui/input/index.js";
import { Progress } from "#lib/components/ui/progress/index.js";
import { Skeleton } from "#lib/components/ui/skeleton/index.js";
import type { WorkshopCalendarEvent } from "#lib/types.js";
import type { WorkshopCalendarItem } from "@dhc/api-client";
import {
	CalendarDays,
	Clock3,
	MapPin,
	Pencil,
	Search,
	Settings2,
	UserRoundCheck,
	Users,
} from "@lucide/svelte";
import {
	dublinInstantTile,
	formatDublinDayAndTime,
} from "#lib/club-calendar.js";
import WorkshopEventModal from "./workshop-event-modal.svelte";

type StatusFilter = "all" | WorkshopCalendarItem["status"];

let {
	workshops = [],
	userId,
	isLoading = false,
	handleEdit,
}: {
	workshops: WorkshopCalendarItem[];
	userId?: string;
	isLoading?: boolean;
	handleEdit?: (workshop: WorkshopCalendarItem) => void;
} = $props();

const statusFilters: { label: string; value: StatusFilter }[] = [
	{ label: "All", value: "all" },
	{ label: "Planned", value: "planned" },
	{ label: "Published", value: "published" },
	{ label: "Finished", value: "finished" },
	{ label: "Cancelled", value: "cancelled" },
];

let search = $state("");
let statusFilter = $state<StatusFilter>("all");
let selectedEvent = $state<WorkshopCalendarEvent | null>(null);
let dialogOpen = $state(false);

const filteredWorkshops = $derived.by(() => {
	const query = search.trim().toLocaleLowerCase();

	return [...workshops]
		.filter((workshop) => {
			const matchesStatus =
				statusFilter === "all" || workshop.status === statusFilter;
			const matchesSearch =
				query.length === 0 ||
				workshop.title.toLocaleLowerCase().includes(query) ||
				workshop.location?.toLocaleLowerCase().includes(query);

			return matchesStatus && matchesSearch;
		})
		.sort((first, second) => {
			const firstIsPast = hasEnded(first);
			const secondIsPast = hasEnded(second);

			if (firstIsPast !== secondIsPast) return firstIsPast ? 1 : -1;
			return Date.parse(first.startDate) - Date.parse(second.startDate);
		});
});

function hasEnded(workshop: WorkshopCalendarItem) {
	return Date.parse(workshop.endDate) < Date.now();
}

function getCapacityPercentage(workshop: WorkshopCalendarItem) {
	if (workshop.isAtCapacity) return 100;
	if (!workshop.maxCapacity) return 0;
	return Math.min(
		100,
		Math.round((workshop.registrationCount / workshop.maxCapacity) * 100),
	);
}

function getStatusVariant(status: WorkshopCalendarItem["status"]) {
	if (status === "planned") return "secondary" as const;
	if (status === "cancelled") return "destructive" as const;
	if (status === "finished") return "outline" as const;
	return "default" as const;
}

function openManager(workshop: WorkshopCalendarItem) {
	selectedEvent = {
		id: workshop.id,
		title: workshop.title,
		start: workshop.startDate,
		end: workshop.endDate,
		workshop,
		isInterested: false,
		isLoading,
		userId: userId ?? "",
		handleEdit,
	};
	dialogOpen = true;
}

function clearFilters() {
	search = "";
	statusFilter = "all";
}
</script>

